using System.Security.Cryptography;
using Revora.ClientDoctor.Core;
using Revora.Launcher.Core;

if (args.Length == 1 && args[0] == "--windows-regression-only")
{
    if (!OperatingSystem.IsWindows()) throw new InvalidOperationException("The Windows regression must run on Windows.");
    await WindowsPartialHashRename();
    Console.WriteLine("PASS Windows partial hash stream disposed before rename");
    return 0;
}

var tests = new (string, Func<Task>)[]
{
    ("Active source rejected", ActiveSourceRejected), ("Disguised PE rejected", DisguisedPeRejected),
    ("Exact passive reusable", ExactPassiveReusable), ("Passive mismatch rejected", PassiveMismatchRejected),
    ("Source preserved", SourcePreserved), ("Separate client constructed", SeparateClientConstructed), ("Nested destination rejected", NestedDestinationRejected),
    ("Root destination rejected", RootDestinationRejected), ("Interrupted download cleans partial", InterruptedDownload),
    ("Repository hash mismatch rejected", DownloadHashMismatch), ("Signature key mismatch rejected", SignatureMismatch),
    ("Manifest payload reproducible", ManifestReproducible), ("Reparse donor rejected", ReparseDonorRejected),
    ("Activation rollback", ActivationRollback), ("Object path deterministic", ObjectPathDeterministic),
    ("Sanitized report excludes source root", ReportSanitized),
    ("Actual version reported", ActualVersionReported), ("Doctor bundle excluded", DoctorBundleExcluded),
    ("Unsupported donor cannot construct", UnsupportedDonorCannotConstruct), ("Case collision rejected", CaseCollisionRejected),
    ("Marked staging recovery", MarkedStagingRecovery), ("Test 2b staging recovered by Test 2c", Test2bStagingRecovery),
    ("Unmarked staging preserved", UnmarkedStagingPreserved),
    ("Build failure report sanitized", BuildFailureReportSanitized)
};
int failures = 0;
foreach ((string name, Func<Task> run) in tests) { try { await run(); Console.WriteLine($"PASS {name}"); } catch (Exception e) { failures++; Console.Error.WriteLine($"FAIL {name}: {e.Message}"); } }
Console.WriteLine($"Total: {tests.Length}, Passed: {tests.Length - failures}, Failed: {failures}");
return failures == 0 ? 0 : 1;

static async Task ActiveSourceRejected() => Assert((await Inventory("bad.exe", "abc"u8.ToArray(), Entry("bad.exe", "passive", "abc"u8.ToArray()))).Files.Single(file => file.RelativePath == "bad.exe").State == DonorFileState.ActiveUntrusted);
static async Task DisguisedPeRejected() => Assert((await Inventory("image.dat", "MZbad"u8.ToArray(), Entry("image.dat", "passive", "MZbad"u8.ToArray()))).Files.Single(file => file.RelativePath == "image.dat").State == DonorFileState.DisguisedExecutable);
static async Task ExactPassiveReusable() => Assert((await Inventory("data.wdf", "abc"u8.ToArray(), Entry("data.wdf", "passive", "abc"u8.ToArray()))).Files.Single(file => file.RelativePath == "data.wdf").State == DonorFileState.ReusablePassive);
static async Task PassiveMismatchRejected() => Assert((await Inventory("data.wdf", "bad"u8.ToArray(), Entry("data.wdf", "passive", "abc"u8.ToArray()))).Files.Single(file => file.RelativePath == "data.wdf").State == DonorFileState.Mismatch);
static async Task SourcePreserved() { string root = Temp(); string p = Path.Combine(root, "data.wdf"); await File.WriteAllTextAsync(p, "abc"); await File.WriteAllTextAsync(Path.Combine(root, "version.dat"), "5165"); _ = await new SourceInventory().InspectAsync(root, Profile(Entry("data.wdf", "passive", "abc"u8.ToArray())), default); Assert(await File.ReadAllTextAsync(p) == "abc"); }
static Task NestedDestinationRejected() { string root = Temp(); AssertThrows<InvalidDataException>(() => SourceInventory.ValidateDestination(root, Path.Combine(root, "clean"))); return Task.CompletedTask; }
static Task RootDestinationRejected() { AssertThrows<InvalidDataException>(() => SourceInventory.ValidateDestination(Temp(), Path.GetPathRoot(Path.GetFullPath(Temp()))!)); return Task.CompletedTask; }
static async Task InterruptedDownload() { var handler = new Handler(_ => throw new TaskCanceledException()); using var http = new HttpClient(handler); string stage = Temp(); await AssertThrowsAsync<TaskCanceledException>(() => new AtomicUpdate(http).StageAsync(stage, [Entry("data.wdf", "passive", "abc"u8.ToArray()) with { DownloadUrl = "https://playrevora.com/object" }], default)); Assert(!Directory.EnumerateFiles(stage, "*.partial", SearchOption.AllDirectories).Any()); }
static async Task DownloadHashMismatch() { using var http = new HttpClient(new Handler(_ => new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent("bad"u8.ToArray()) })); await AssertThrowsAsync<CryptographicException>(() => new AtomicUpdate(http).StageAsync(Temp(), [Entry("data.wdf", "passive", "abc"u8.ToArray()) with { DownloadUrl = "https://playrevora.com/object" }], default)); }
static Task SignatureMismatch() { using ECDsa a = ECDsa.Create(ECCurve.NamedCurves.nistP256); using ECDsa b = ECDsa.Create(ECCurve.NamedCurves.nistP256); byte[] payload = System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(Profile(Entry("Conquer.exe", "active", "abc"u8.ToArray()))); byte[] sig = a.SignData(payload, HashAlgorithmName.SHA256, DSASignatureFormat.Rfc3279DerSequence); byte[] env = System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(new SignedEnvelope("test", "ECDSA-P256-SHA256", Convert.ToBase64String(payload), Convert.ToBase64String(sig))); AssertThrows<CryptographicException>(() => new ManifestVerifier(b.ExportSubjectPublicKeyInfo(), "test").VerifyAndRead(env)); return Task.CompletedTask; }
static Task ManifestReproducible() { ClientProfile profile = Profile(Entry("Conquer.exe", "active", "abc"u8.ToArray())); Assert(ProfileCodec.SerializeCanonical(profile).SequenceEqual(ProfileCodec.SerializeCanonical(profile))); return Task.CompletedTask; }
static async Task ReparseDonorRejected() { string root = Temp(); string outside = Path.Combine(Temp(), "data.wdf"); await File.WriteAllTextAsync(outside, "abc"); File.CreateSymbolicLink(Path.Combine(root, "data.wdf"), outside); await AssertThrowsAsync<InvalidDataException>(() => new SourceInventory().InspectAsync(root, Profile(Entry("data.wdf", "passive", "abc"u8.ToArray())), default)); }
static Task ActivationRollback() { string parent = Temp(); string current = Path.Combine(parent, "current"); string stage = Path.Combine(parent, "stage"); string rollback = Path.Combine(parent, "rollback"); Directory.CreateDirectory(current); Directory.CreateDirectory(stage); File.WriteAllText(Path.Combine(current, "old"), "old"); File.WriteAllText(Path.Combine(stage, "new"), "new"); AtomicUpdate.Activate(current, stage, rollback); Assert(File.Exists(Path.Combine(current, "new")) && File.Exists(Path.Combine(rollback, "old"))); return Task.CompletedTask; }
static Task ObjectPathDeterministic() { const string h = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"; Assert($"objects/sha256/{h[..2]}/{h}" == "objects/sha256/aa/" + h); return Task.CompletedTask; }
static async Task SeparateClientConstructed() { string source = Temp(); await File.WriteAllTextAsync(Path.Combine(source, "data.wdf"), "data"); await File.WriteAllTextAsync(Path.Combine(source, "version.dat"), "5165"); byte[] executable = "MZclean-repository-copy"u8.ToArray(); ClientFile data = Entry("data.wdf", "passive", "data"u8.ToArray()); ClientFile version = Entry("version.dat", "passive", "5165"u8.ToArray()); ClientFile active = Entry("Conquer.exe", "active", executable) with { DownloadUrl = "https://playrevora.com/object" }; ClientProfile profile = new(1, 5165, "playrevora.com", 9958, 9959, "Conquer.exe", [data, version, active], "testing", "doctor-reconstruction-5165-test", ["blacknull"], 19045, "disabled"); DoctorInventory inventory = await new SourceInventory().InspectAsync(source, profile, default); using var http = new HttpClient(new Handler(_ => new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(executable) })); string destination = Path.Combine(Path.GetDirectoryName(source)!, Guid.NewGuid().ToString("N")); await new ClientConstructor(http).BuildAsync(source, destination, profile, inventory, default); Assert(await File.ReadAllTextAsync(Path.Combine(source, "data.wdf")) == "data" && File.Exists(Path.Combine(destination, "Conquer.exe"))); }
static async Task ReportSanitized() { DoctorInventory inventory = await Inventory("data.wdf", "abc"u8.ToArray(), Entry("data.wdf", "passive", "abc"u8.ToArray())); string report = SanitizedReport.Create(inventory, "test-1", "1"); Assert(!report.Contains(Path.GetTempPath(), StringComparison.OrdinalIgnoreCase)); }
static async Task ActualVersionReported() { DoctorInventory i = await Inventory("data.wdf", "abc"u8.ToArray(), Entry("data.wdf", "passive", "abc"u8.ToArray())); Assert(i.DetectedPatch == 5165 && i.PatchEvidence == "version.dat=5165"); }
static async Task DoctorBundleExcluded() { DoctorInventory i = await Inventory("Revora.ClientDoctor.exe", "MZdoctor"u8.ToArray(), Entry("data.wdf", "passive", "abc"u8.ToArray())); Assert(i.Files.Single(f => f.RelativePath == "Revora.ClientDoctor.exe").State == DonorFileState.SelfExcluded); }
static async Task UnsupportedDonorCannotConstruct() { string source = Temp(); await File.WriteAllTextAsync(Path.Combine(source, "version.dat"), "5156"); ClientProfile p = Profile(Entry("data.wdf", "passive", "abc"u8.ToArray())); DoctorInventory i = await new SourceInventory().InspectAsync(source, p, default); using var http = new HttpClient(); await AssertThrowsAsync<InvalidDataException>(() => new ClientConstructor(http).BuildAsync(source, Path.Combine(Path.GetDirectoryName(source)!, Guid.NewGuid().ToString("N")), p, i, default)); }
static async Task CaseCollisionRejected() { if (OperatingSystem.IsWindows()) return; string root = Temp(); await File.WriteAllTextAsync(Path.Combine(root, "A.dat"), "a"); await File.WriteAllTextAsync(Path.Combine(root, "a.dat"), "b"); await AssertThrowsAsync<InvalidDataException>(() => new SourceInventory().InspectAsync(root, Profile(Entry("A.dat", "passive", "a"u8.ToArray())), default)); }
static async Task MarkedStagingRecovery() { string source = Temp(); await File.WriteAllTextAsync(Path.Combine(source, "data.wdf"), "data"); await File.WriteAllTextAsync(Path.Combine(source, "version.dat"), "5165"); byte[] activeBytes = "MZrepository"u8.ToArray(); ClientProfile profile = ReconstructionProfile(activeBytes); DoctorInventory inventory = await new SourceInventory().InspectAsync(source, profile, default); string destination = Path.Combine(Path.GetDirectoryName(source)!, Guid.NewGuid().ToString("N")); string stage = destination + ".staging"; Directory.CreateDirectory(stage); await File.WriteAllTextAsync(Path.Combine(stage, ".revora-client-doctor-staging.json"), System.Text.Json.JsonSerializer.Serialize(new { schemaVersion = 1, owner = "Revora.ClientDoctor", buildId = profile.BuildId })); await File.WriteAllTextAsync(Path.Combine(stage, "stale"), "stale"); using var http = new HttpClient(new Handler(_ => new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(activeBytes) })); BuildResult result = await new ClientConstructor(http).BuildAsync(source, destination, profile, inventory, default); Assert(result.Success && Directory.Exists(destination) && !Directory.Exists(stage)); }
static async Task Test2bStagingRecovery() { string source = Temp(); await File.WriteAllTextAsync(Path.Combine(source, "data.wdf"), "data"); await File.WriteAllTextAsync(Path.Combine(source, "version.dat"), "5165"); byte[] activeBytes = "MZrepository"u8.ToArray(); ClientProfile profile = ReconstructionProfile(activeBytes) with { BuildId = "doctor-reconstruction-5165-test-2c" }; DoctorInventory inventory = await new SourceInventory().InspectAsync(source, profile, default); string destination = Path.Combine(Path.GetDirectoryName(source)!, Guid.NewGuid().ToString("N")); string stage = destination + ".staging"; Directory.CreateDirectory(stage); await File.WriteAllTextAsync(Path.Combine(stage, ".revora-client-doctor-staging.json"), System.Text.Json.JsonSerializer.Serialize(new { schemaVersion = 1, owner = "Revora.ClientDoctor", buildId = "doctor-reconstruction-5165-test-2b" })); await File.WriteAllTextAsync(Path.Combine(stage, "stale"), "stale"); using var http = new HttpClient(new Handler(_ => new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(activeBytes) })); BuildResult result = await new ClientConstructor(http).BuildAsync(source, destination, profile, inventory, default); Assert(result.Success && Directory.Exists(destination) && !Directory.Exists(stage)); }
static async Task UnmarkedStagingPreserved() { string source = Temp(); await File.WriteAllTextAsync(Path.Combine(source, "data.wdf"), "data"); await File.WriteAllTextAsync(Path.Combine(source, "version.dat"), "5165"); byte[] activeBytes = "MZrepository"u8.ToArray(); ClientProfile profile = ReconstructionProfile(activeBytes); DoctorInventory inventory = await new SourceInventory().InspectAsync(source, profile, default); string destination = Path.Combine(Path.GetDirectoryName(source)!, Guid.NewGuid().ToString("N")); string stage = destination + ".staging"; Directory.CreateDirectory(stage); await File.WriteAllTextAsync(Path.Combine(stage, "owner-file"), "preserve"); using var http = new HttpClient(); await AssertThrowsAsync<IOException>(() => new ClientConstructor(http).BuildAsync(source, destination, profile, inventory, default)); Assert(File.Exists(Path.Combine(stage, "owner-file"))); }
static Task BuildFailureReportSanitized() { var error = new ClientBuildException("move", "data/file.wdf", new IOException("private absolute path must not appear"), true); string report = SanitizedReport.CreateBuildFailure(error, "doctor-reconstruction-5165-test", "2b"); Assert(report.Contains("data/file.wdf", StringComparison.Ordinal) && report.Contains("FileAccess", StringComparison.Ordinal) && !report.Contains("private absolute", StringComparison.Ordinal)); return Task.CompletedTask; }
static async Task WindowsPartialHashRename() { byte[] content = "signed-test-object"u8.ToArray(); ClientProfile profile = ReconstructionProfile(content); using ECDsa key = ECDsa.Create(ECCurve.NamedCurves.nistP256); byte[] payload = ProfileCodec.SerializeCanonical(profile); byte[] signature = key.SignData(payload, HashAlgorithmName.SHA256, DSASignatureFormat.Rfc3279DerSequence); byte[] envelope = System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(new SignedEnvelope(LauncherPolicy.TestingSigningKeyId, "ECDSA-P256-SHA256", Convert.ToBase64String(payload), Convert.ToBase64String(signature))); ClientProfile signed = new ManifestVerifier(key.ExportSubjectPublicKeyInfo(), LauncherPolicy.TestingSigningKeyId).VerifyAndRead(envelope); string stage = Temp(); using var http = new HttpClient(new Handler(_ => new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(content) })); await new AtomicUpdate(http).StageAsync(stage, signed.Files, default); string destination = Path.Combine(stage, "Conquer.exe"); Assert(File.Exists(destination) && !File.Exists(destination + ".partial")); await using (FileStream exclusive = new(destination, FileMode.Open, FileAccess.ReadWrite, FileShare.None)) { Assert(exclusive.Length == content.Length); } string moved = Path.Combine(stage, "renamed.exe"); File.Move(destination, moved); Assert(File.Exists(moved) && !File.Exists(destination) && !Directory.EnumerateFiles(stage, "*.partial", SearchOption.AllDirectories).Any()); }
static async Task<DoctorInventory> Inventory(string name, byte[] bytes, ClientFile expected) { string root = Temp(); await File.WriteAllBytesAsync(Path.Combine(root, name), bytes); await File.WriteAllTextAsync(Path.Combine(root, "version.dat"), "5165"); return await new SourceInventory().InspectAsync(root, Profile(expected), default); }
static ClientFile Entry(string path, string role, byte[] bytes) => new(path, bytes.Length, Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(), null, role);
static ClientProfile ReconstructionProfile(byte[] activeBytes) => new(1, 5165, "playrevora.com", 9958, 9959, "Conquer.exe", [Entry("data.wdf", "passive", "data"u8.ToArray()), Entry("version.dat", "passive", "5165"u8.ToArray()), Entry("Conquer.exe", "active", activeBytes) with { DownloadUrl = "https://playrevora.com/object" }], "testing", "doctor-reconstruction-5165-test", ["blacknull"], 19045, "disabled");
static ClientProfile Profile(ClientFile file) { ClientFile version = Entry("version.dat", "passive", "5165"u8.ToArray()); return new(1, 5165, "playrevora.com", 9958, 9959, "Conquer.exe", file.Path == "Conquer.exe" ? [file, version] : [file, version, Entry("Conquer.exe", "active", "abc"u8.ToArray())], "testing", "doctor-reconstruction-5165-test", ["blacknull"], 19045, "disabled"); }
static string Temp() { string p = Path.Combine(Path.GetTempPath(), "revora-doctor-tests", Guid.NewGuid().ToString("N")); Directory.CreateDirectory(p); return p; }
static void Assert(bool value) { if (!value) throw new InvalidOperationException("Assertion failed."); }
static void AssertThrows<T>(Action action) where T : Exception { try { action(); } catch (T) { return; } throw new InvalidOperationException($"Expected {typeof(T).Name}."); }
static async Task AssertThrowsAsync<T>(Func<Task> action) where T : Exception { try { await action(); } catch (T) { return; } throw new InvalidOperationException($"Expected {typeof(T).Name}."); }
sealed class Handler(Func<HttpRequestMessage, HttpResponseMessage> callback) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) => Task.FromResult(callback(request)); }
